# "Separate editions in folder names" (profile naming.editions)
EDITIONS = ("off", "edition", "edition_year")


# --- naming.py:61
EDITION_VAR = {"edition": "_edition_kind", "edition_year": "_edition"}


# --- naming.py:62
_VINYL = re.compile(r'vinyl|\b(?:7|10|12)\s*(?:"|\u201d|\u2033|\'\'|-?inch\b|in\b)', re.I)


# --- naming.py:65
def _disc_kind(low: str) -> str:
    """A disc's edition word from its media (lower case): SACD (MusicBrainz "Hybrid SACD (SACD
    layer, ...)", "SACD", Discogs "SACD, Hybrid"), DVD-A ("DVD-Audio"), Blu-ray, else CD - an
    SACD's CD layer and a DualDisc's CD side too ("SACD" holds "CD": asked first). As the
    presets' Picard scripts have it (_edkind)."""
    if "sacd layer" in low:
        return "SACD"
    if "cd layer" in low or "cd side" in low:
        return "CD"
    if "sacd" in low:
        return "SACD"
    if "dvd-audio" in low:
        return "DVD-A"
    if "blu-ray" in low:
        return "Blu-ray"
    return "CD"


# --- naming.py:83
def edition_parts(tags: dict) -> tuple[str, str]:
    """(kind, reissue year) of a release from its tags. Kind from the media tag: Vinyl
    (vinyl, 7"/10"/12"), WEB (digital), Tape (cassette), SACD, DVD-A, Blu-ray (_disc_kind),
    CD for anything else, "" when
    there is no media tag. The reissue year is the release's own date year when it is not
    the original year. "~edition_media" (the release's first disc, set by the planner)
    wins over the file's own media, so a set mixing media stays in one folder."""
    def first(k):
        v = tags.get(k)
        v = (v if isinstance(v, list) else [v]) if v not in (None, "") else []
        return str(v[0]).strip() if v else ""
    media = first("~edition_media") or first("media")
    if not media:
        return "", ""
    low = media.lower()
    # a download: MusicBrainz "Digital Media", the Discogs plugin's "File, FLAC, Album" (Sunn O))) 2026)
    web = "digital" in low or low.split(",")[0].strip() in ("file", "download")
    kind = "Vinyl" if _VINYL.search(media) else "WEB" if web else "Tape" if "cassette" in low else _disc_kind(low)
    if first("~edition_media"):          # the release's first disc decides, its dates too
        orig = (first("~edition_originalyear") or first("~edition_originaldate"))[:4]
        year = first("~edition_date")[:4]
    else:
        orig = (first("originalyear") or first("originaldate"))[:4]
        year = first("date")[:4]
    reissue = year if year.isdigit() and orig.isdigit() and year != orig else ""
    return kind, reissue


# --- naming.py:113
# ED-1/ED-2: what is always marked, with the pressing's own year; ED-3: a CD or download is
# marked only as a newer remaster or reissue
_ALWAYS_MARKED = {"Vinyl": "Vinyl Rip", "Tape": "Tape Rip", "SACD": "SACD", "DVD-A": "DVD-A", "Blu-ray": "Blu-ray"}


# --- naming.py:116
def _pressing_year(tags) -> str:
    def first(k):
        v = tags.get(k)
        v = (v if isinstance(v, list) else [v]) if v not in (None, "") else []
        return str(v[0]).strip() if v else ""
    y = (first("~edition_date") if first("~edition_media") else first("date"))[:4]
    return y if y.isdigit() else ""


# --- naming.py:127
# ED-3b: the edition names a release may call itself by ("Deluxe Edition" in Discogs's format, the
# release's title or comment): the edition is labelled with that name, not "Remaster"
_EDITION_NAME = re.compile(r"\b((?:super\s+)?deluxe|expanded|(?:\d{1,3}(?:st|nd|rd|th)\s+)?anniversary|special|"
                           r"collector'?s|legacy|definitive|complete)\s+edition\b", re.I)


# --- naming.py:131
def edition_name(tags) -> str:
    """ED-3b: the edition name the release itself carries - its media (Discogs's "CD, Album, Deluxe
    Edition, Stereo"), its comment or its title ("Echoes of Life (Deluxe Edition)") - in title case
    ("Deluxe Edition", "25th Anniversary Edition"); "" for none."""
    text = " ".join(str(x) for k in ("~edition_media", "media", "releasecomment", "~releasecomment", "album")
                    for x in (tags.get(k) if isinstance(tags.get(k), list) else [tags.get(k) or ""]))
    m = _EDITION_NAME.search(text)
    if not m:
        return ""
    words = " ".join(m.group(0).split())
    return " ".join(w if w[:1].isdigit() else w[:1].upper() + w[1:].lower() for w in words.split())


# --- naming.py:144
def _reissue_word(tags) -> str:
    """ED-3: "Reissue" when the release calls itself a reissue and not a remaster, else
    "Remaster"; ED-3b (decided 2026-11-20): the release's own edition name when it carries one
    ("Deluxe Edition")."""
    named = edition_name(tags)
    if named:
        return named
    text = " ".join(str(x) for k in ("~edition_media", "media", "releasecomment", "~releasecomment")
                    for x in (tags.get(k) if isinstance(tags.get(k), list) else [tags.get(k) or ""])).lower()
    return "Reissue" if "reissue" in text and "remaster" not in text else "Remaster"


# --- naming.py:156
def _unofficial(tags) -> bool:
    """MusicBrainz's release status "bootleg", or Discogs's "Unofficial Release" in the media."""
    def vals(k):
        v = tags.get(k)
        return [str(x) for x in (v if isinstance(v, list) else [v or ""])]
    return any(x.strip().lower() == "bootleg" for x in vals("releasestatus")) or any(
        "unofficial release" in x.lower() for k in ("media", "~edition_media") for x in vals(k))


# --- naming.py:165
def edition(tags: dict, mode: str = "edition_year") -> str:
    """The edition text for a folder and the album tag (ED-1 to ED-4): an SACD, DVD-Audio or
    Blu-ray always "1999 SACD"; a vinyl or tape rip always "1977 Vinyl Rip", "1984 Tape Rip"
    (the pressing's own year); a CD or download only when it is newer than the original:
    "2015 Remaster" ("2015 Reissue" when the release says reissue). "" for the original CD or
    download, unknown media or mode "off". ED-5: hi-res audio ("~edition_hd") on a CD-type
    or download edition adds HD: "HD", "2015 Remaster HD"; an album known ("~edition_unproven")
    shows only "HD". Mode "edition": the kind alone ("Vinyl Rip", "SACD", "Remaster").""" 
    if mode not in EDITION_VAR:
        return ""
    hd = bool(tags.get("~edition_hd"))
    if tags.get("~edition_unproven"):
        # ED-5: an album known shows only its HD - never a vinyl rip's (vinyl never adds HD: its
        # pressing unproven, the copy is a vinyl rip by its own evidence, VIN-3's ~rip_vinyl)
        return "HD" if hd and not tags.get("~rip_vinyl") and edition_parts(tags)[0] != "Vinyl" else ""
    kind, reissue = edition_parts(tags)
    if kind in _ALWAYS_MARKED:
        word = _ALWAYS_MARKED[kind]
        return word if mode == "edition" else f"{_pressing_year(tags)} {word}".strip()
    if not kind or not reissue:
        return "HD" if hd else ""                   # the original CD or download: no suffix (ED-3), or HD (ED-5)
    if _unofficial(tags):
        # ED-7: a bootleg is no remaster or reissue of anything (Talking Heads - The Complete Gig:
        # "[1991 Remaster]" for a 1991 bootleg of a 1990 show)
        return "HD" if hd else ""
    word = _reissue_word(tags) + (" HD" if hd else "")
    return word if mode == "edition" else f"{reissue} {word}"


# --- plan.py:62
# ED-6: the version marks that only say "remastered" or "reissued" (a year-named "2009 Remaster"
# or "Remix 2024" says more and stays)
_GENERIC_VERSION_MARK = re.compile(r"\s*[\(\[](?:digitally\s+)?(?:remastered|remaster|reissue|reissued)"
                                   r"(?:\s+edition|\s+version)?[\)\]]\s*$", re.I)
